const { createApp } = Vue;

createApp({
  data() {
    return {
      count: 0
    };
  },
  methods: {
    increment() {
      this.count++;
    },
    decrement() {
      this.count--;
    }
  },
  template: `
    <div>
      <h1>Counter</h1>
      <p>Count: {{ count }}</p>
      <button @click="increment">+</button>
      <button @click="decrement">-</button>
    </div>
  `
}).mount('#root');

const { createApp } = Vue;

createApp({
  data() {
    return {
      count: 0
    };
  },
  computed: {
    isEven() {
      return this.count % 2 === 0;
    }
  },
  methods: {
    increment() { this.count++; },
    decrement() { this.count--; }
  },
  template: `
    <div>
      <h1>Counter</h1>
      <p>Count: {{ count }} ({{ isEven ? 'Even' : 'Odd' }})</p>
      <button @click="increment">+</button>
      <button @click="decrement">-</button>
    </div>
  `
}).mount('#root');

